import * as Phaser from "phaser";
import { ASSET_KEYS, DESKS_FRAME_KEYS } from "../../../common/assets";
import { INTERACTIVE_OBJECT_TYPE } from "../../../common/constants";
import { type DataManager } from "../../../common/data-manager";
import {
  type DeskType,
  type TiledRegiDeskObject,
} from "../../../common/tiled/types";
import type { CustomObject } from "../../../common/types";
import { InteractiveObjectComponent } from "../../../components/interactive-object-component";

export class InteractiveDesk
  extends Phaser.Physics.Arcade.Image
  implements CustomObject
{
  private config: TiledRegiDeskObject;
  private dataManager: DataManager;

  constructor(
    scene: Phaser.Scene,
    config: TiledRegiDeskObject,
    storyFlag: string,
    dataManager: DataManager,
    onClick: (id: number) => boolean,
  ) {
    super(
      scene,
      config.x,
      config.y,
      ASSET_KEYS.DESKS,
      DESKS_FRAME_KEYS[`${config.deskType}_unpressed.png`],
    );

    this.config = config;
    this.dataManager = dataManager;

    scene.add.existing(this);
    scene.physics.add.existing(this);
    this.setOrigin(0, 0).setImmovable(true);
    this.setToTop();
    this.setDepth(5);

    new InteractiveObjectComponent(this, INTERACTIVE_OBJECT_TYPE.AUTO, () => {
      if (this.dataManager.hasStoryFlagValues({ [storyFlag]: "completed" })) {
        return true;
      }

      this.setFrame(
        DESKS_FRAME_KEYS[this.getDeskFrameKey(this.config.deskType, true)],
      );
      const correct = onClick(config.id);
      if (correct) {
        setTimeout(() => {
          if (this.active) {
            this.setFrame(
              DESKS_FRAME_KEYS[
                this.getDeskFrameKey(this.config.deskType, false)
              ],
            );
          }
        }, 300);
      }
      return true;
    });

    this.disableObject();
  }

  public activate(): void {
    this.active = true;
  }

  public deactivate(): void {
    this.active = false;
  }

  public press(): void {
    this.setFrame(
      DESKS_FRAME_KEYS[this.getDeskFrameKey(this.config.deskType, true)],
    );
  }

  public unPress(): void {
    this.setFrame(
      DESKS_FRAME_KEYS[this.getDeskFrameKey(this.config.deskType, false)],
    );
  }

  public disableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = false;
    this.active = false;
    this.visible = false;
  }

  public enableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = true;
    this.visible = true;
    this.active = true;
  }

  private getDeskFrameKey(
    deskType: DeskType,
    pressed: boolean,
  ): keyof typeof DESKS_FRAME_KEYS {
    return `${deskType}_${pressed ? "pressed.png" : "unpressed.png"}`;
  }
}
