import CAT_CASTLE_BACKGROUND from "../assets/data/levels/cat_catsle/cat_catsle_background.png";
import CAT_CASTLE_FOREGROUND from "../assets/data/levels/cat_catsle/cat_catsle_foreground.png";
import CATSLE_EVENTS from "../assets/data/levels/cat_catsle/events.json";
import CATSLE_NPCS from "../assets/data/levels/cat_catsle/npcs.json";
import CATSLE_READABLES from "../assets/data/levels/cat_catsle/readables.json";
import SPOT1_JSON from "../assets/data/spot_the_diff/spot1.json";
import SPOT1_IMG from "../assets/data/spot_the_diff/spot1.png";
import SPOT2_JSON from "../assets/data/spot_the_diff/spot2.json";
import SPOT2_IMG from "../assets/data/spot_the_diff/spot2.png";
import SPOT3_JSON from "../assets/data/spot_the_diff/spot3.json";
import SPOT3_IMG from "../assets/data/spot_the_diff/spot3.png";
import SPOT4_JSON from "../assets/data/spot_the_diff/spot4.json";
import SPOT4_IMG from "../assets/data/spot_the_diff/spot4.png";
import LADYCAT_JSON from "../assets/images/npcs/catsle/ladycat.json";
import LADYCAT_IMG from "../assets/images/npcs/catsle/ladycat.png";
import LION_JSON from "../assets/images/npcs/catsle/lion.json";
import LION_IMG from "../assets/images/npcs/catsle/lion.png";
import MAGECAT_JSON from "../assets/images/npcs/catsle/magecat.json";
import MAGECAT_IMG from "../assets/images/npcs/catsle/magecat.png";
import PENGCAT_JSON from "../assets/images/npcs/catsle/pengcat.json";
import PENGCAT_IMG from "../assets/images/npcs/catsle/pengcat.png";
import HOTDOG_JSON from "../assets/images/npcs/western/hotdog.json";
import HOTDOG_IMG from "../assets/images/npcs/western/hotdog.png";
import SPOT_JSON from "../assets/images/npcs/western/spot.json";
import SPOT_IMG from "../assets/images/npcs/western/spot.png";
import BUTTONS_JSON from "../assets/images/world_objects/buttons.json";
import BUTTONS_IMG from "../assets/images/world_objects/buttons.png";
import DOORS_JSON from "../assets/images/world_objects/doors.json";
import DOORS_IMG from "../assets/images/world_objects/doors.png";
import GATES_JSON from "../assets/images/world_objects/gates.json";
import GATES_IMG from "../assets/images/world_objects/gates.png";
import JAIL_BARS_JSON from "../assets/images/world_objects/jail_bars.json";
import JAIL_BARS_IMG from "../assets/images/world_objects/jail_bars.png";
import DOGPOSTER_ASTA_IMG from "../assets/images/world_objects/pet_posters/asta.jpg";
import DOGPOSTER_BAO_IMG from "../assets/images/world_objects/pet_posters/bao.jpg";
import DOGPOSTER_BINGBING_IMG from "../assets/images/world_objects/pet_posters/bingbing.jpg";
import DOGPOSTER_PIGU_IMG from "../assets/images/world_objects/pet_posters/pigu.jpg";
import DOGPOSTER_PIPER_IMG from "../assets/images/world_objects/pet_posters/piper.jpg";
import DOGPOSTER_SID_IMG from "../assets/images/world_objects/pet_posters/sid.jpg";
import DOGPOSTER_TIMBER_IMG from "../assets/images/world_objects/pet_posters/timber.jpg";
import WANTED_POSTER_JSON from "../assets/images/world_objects/pet_posters/wanted_poster.json";
import WANTED_POSTER_IMG from "../assets/images/world_objects/pet_posters/wanted_poster.png";
import DESKS_JSON from "../assets/images/world_objects/regi_desk.json";
import DESKS_IMG from "../assets/images/world_objects/regi_desk.png";
import BARK_SOUND from "../assets/sounds/bark.mp3";
import MEOW_SOUND from "../assets/sounds/meow.mp3";
import { ASSET_KEYS } from "../common/assets";
import { BasePreloadScene } from "./base-preload-scene";
import { SCENE_KEYS } from "./scene-keys";

export class KittyCityPreloadScene extends BasePreloadScene {
  constructor() {
    super(SCENE_KEYS.KITTY_CITY_PRELOAD_SCENE);
  }

  public preload(): void {
    super.preload();
    this.#loadKittyCityAssets();
  }

  public create(): void {
    super.create();
    this.#createKittyCityAnimations();
  }

  #loadKittyCityAssets(): void {
    // Load level
    this.load.image(ASSET_KEYS.CAT_CATSLE_BACKGROUND, CAT_CASTLE_BACKGROUND);
    this.load.image(ASSET_KEYS.CAT_CATSLE_FOREGROUND, CAT_CASTLE_FOREGROUND);
    this.load.tilemapTiledJSON(ASSET_KEYS.CAT_CATSLE_LEVEL, CAT_CASTLE_LEVEL);

    // Load cat NPCs
    this.load.aseprite(ASSET_KEYS.LADYCAT, LADYCAT_IMG, LADYCAT_JSON);
    this.load.aseprite(ASSET_KEYS.LION, LION_IMG, LION_JSON);
    this.load.aseprite(ASSET_KEYS.MAGECAT, MAGECAT_IMG, MAGECAT_JSON);
    this.load.aseprite(ASSET_KEYS.PENGCAT, PENGCAT_IMG, PENGCAT_JSON);

    // Load gates atlas
    this.load.atlas(ASSET_KEYS.GATES, GATES_IMG, GATES_JSON);

    // Load jail bars atlas
    this.load.atlas(ASSET_KEYS.JAIL_BARS, JAIL_BARS_IMG, JAIL_BARS_JSON);

    // Load zone-specific data
    this.load.json(ASSET_KEYS.EVENTS, CATSLE_EVENTS);
    this.load.json(ASSET_KEYS.NPCS, CATSLE_NPCS);
    this.load.json(ASSET_KEYS.READABLE_MESSAGES, CATSLE_READABLES);

    // Load buttons
    this.load.atlas(ASSET_KEYS.BUTTONS, BUTTONS_IMG, BUTTONS_JSON);

    // Load doors
    this.load.aseprite(ASSET_KEYS.DOORS, DOORS_IMG, DOORS_JSON);

    this.load.aseprite(ASSET_KEYS.DESKS, DESKS_IMG, DESKS_JSON);

    // Load dog posters
    this.load.image(ASSET_KEYS.DOGPOSTER_ASTA, DOGPOSTER_ASTA_IMG);
    this.load.image(ASSET_KEYS.DOGPOSTER_BAO, DOGPOSTER_BAO_IMG);
    this.load.image(ASSET_KEYS.DOGPOSTER_BINGBING, DOGPOSTER_BINGBING_IMG);
    this.load.image(ASSET_KEYS.DOGPOSTER_PIGU, DOGPOSTER_PIGU_IMG);
    this.load.image(ASSET_KEYS.DOGPOSTER_PIPER, DOGPOSTER_PIPER_IMG);
    this.load.image(ASSET_KEYS.DOGPOSTER_SID, DOGPOSTER_SID_IMG);
    this.load.image(ASSET_KEYS.DOGPOSTER_TIMBER, DOGPOSTER_TIMBER_IMG);

    // Load wanted poster atlas
    this.load.atlas(
      ASSET_KEYS.WANTED_POSTER,
      WANTED_POSTER_IMG,
      WANTED_POSTER_JSON,
    );

    // Load hotdog NPC
    this.load.aseprite(ASSET_KEYS.HOTDOG, HOTDOG_IMG, HOTDOG_JSON);

    // Load spot NPC
    this.load.aseprite(ASSET_KEYS.SPOT, SPOT_IMG, SPOT_JSON);

    // Load spot the difference assets
    const spotAssets = [
      { key: "spot1", img: SPOT1_IMG, json: SPOT1_JSON },
      { key: "spot2", img: SPOT2_IMG, json: SPOT2_JSON },
      { key: "spot3", img: SPOT3_IMG, json: SPOT3_JSON },
      { key: "spot4", img: SPOT4_IMG, json: SPOT4_JSON },
    ];
    for (const spot of spotAssets) {
      this.load.image(spot.key, spot.img);
      this.load.json(`${spot.key}_data`, spot.json);
    }

    // Load sounds
    this.load.audio(ASSET_KEYS.BARK_SFX, BARK_SOUND);
    this.load.audio(ASSET_KEYS.MEOW_SFX, MEOW_SOUND);
  }

  #createKittyCityAnimations(): void {
    this.anims.createFromAseprite(ASSET_KEYS.LADYCAT);
    this.anims.createFromAseprite(ASSET_KEYS.LION);
    this.anims.createFromAseprite(ASSET_KEYS.MAGECAT);
    this.anims.createFromAseprite(ASSET_KEYS.PENGCAT);
    this.anims.createFromAseprite(ASSET_KEYS.HOTDOG);
    this.anims.createFromAseprite(ASSET_KEYS.SPOT);
  }
}
