import * as Phaser from "phaser";
import { ASSET_KEYS, NPC_ANIMATION_KEYS } from "../../common/assets";
import { DIRECTION } from "../../common/constants";
import { type AnimationConfig } from "../../components/animation-component";
import { InputComponent } from "../../components/input-component";
import { CHARACTER_STATES } from "../../components/state-machine/states/character-states";
import { IdleState } from "../../components/state-machine/states/idle-state";
import { MoveState } from "../../components/state-machine/states/move-state";
import { CharacterObject } from "../common/character-object";
import type { Gate } from "../objects/gate";

/**
 * Simple racing cat that follows the gate path
 */
class RacingCat extends CharacterObject {
  constructor(config: {
    scene: Phaser.Scene;
    position: { x: number; y: number };
    animationConfig: AnimationConfig;
  }) {
    super({
      id: `racing-cat-${Phaser.Math.RND.uuid()}`,
      scene: config.scene,
      position: config.position,
      assetKey: ASSET_KEYS.LADYCAT,
      frame: 0,
      isPlayer: false,
      animationConfig: config.animationConfig,
      speed: 0,
      inputComponent: new InputComponent(),
      isInvulnerable: true,
      maxHP: 1,
      shouldFlipLeft: true,
    });

    this.setOrigin(0, 0);
    this._stateMachine.addState(new IdleState(this));
    this._stateMachine.addState(new MoveState(this));
    this._stateMachine.setState(CHARACTER_STATES.IDLE_STATE);
    this.enableObject();
  }

  public setMoveState(): void {
    this._stateMachine.setState(CHARACTER_STATES.MOVE_STATE);
  }

  public setIdleState(): void {
    this._stateMachine.setState(CHARACTER_STATES.IDLE_STATE);
  }
}

export type RacingCatManagerConfig = {
  scene: Phaser.Scene;
  gates: Map<number, Gate>;
  numLaps: number;
  raceTime: number; // seconds
};

/**
 * Manages the racing cat that follows the gate path
 */
export class RacingCatManager {
  #scene: Phaser.Scene;
  #gates: Map<number, Gate>;
  #numLaps: number;
  #raceTime: number;
  #racingCat: RacingCat | null = null;
  #racePath: { x: number; y: number }[] = [];
  #racePathDistance = 0;
  #raceStartTime = 0;

  constructor(config: RacingCatManagerConfig) {
    this.#scene = config.scene;
    this.#gates = config.gates;
    this.#numLaps = config.numLaps;
    this.#raceTime = config.raceTime;
  }

  /**
   * Builds the race path from gates
   */
  public buildRacePath(): void {
    this.#racePath = [];
    this.#racePathDistance = 0;

    // Get all gates sorted by order
    const gates = Array.from(this.#gates.values()).sort(
      (a, b) => a.order - b.order,
    );

    if (gates.length === 0) {
      return;
    }

    // Build path for specified number of laps
    for (let lap = 0; lap < this.#numLaps; lap++) {
      gates.forEach((gate) => {
        const centerX = gate.x + gate.width / 2;
        const centerY = gate.y + gate.height / 2;
        this.#racePath.push({ x: centerX, y: centerY });
      });
    }

    // Calculate total distance
    for (let i = 0; i < this.#racePath.length - 1; i++) {
      const dx = this.#racePath[i + 1].x - this.#racePath[i].x;
      const dy = this.#racePath[i + 1].y - this.#racePath[i].y;
      this.#racePathDistance += Math.hypot(dx, dy);
    }
  }

  /**
   * Creates the racing cat NPC
   */
  public createRacingCat(): void {
    // Destroy existing cat if any
    this.destroyRacingCat();

    if (this.#racePath.length === 0) {
      return;
    }

    const startPos = this.#racePath[0];

    // Create animation config for the cat
    const animationConfig: AnimationConfig = {
      IDLE_DOWN: {
        key: NPC_ANIMATION_KEYS.LADYCAT_IDLE_RIGHT,
        repeat: -1,
        ignoreIfPlaying: true,
      },
      IDLE_UP: {
        key: NPC_ANIMATION_KEYS.LADYCAT_IDLE_LEFT,
        repeat: -1,
        ignoreIfPlaying: true,
      },
      IDLE_LEFT: {
        key: NPC_ANIMATION_KEYS.LADYCAT_IDLE_LEFT,
        repeat: -1,
        ignoreIfPlaying: true,
      },
      IDLE_RIGHT: {
        key: NPC_ANIMATION_KEYS.LADYCAT_IDLE_RIGHT,
        repeat: -1,
        ignoreIfPlaying: true,
      },
      WALK_DOWN: {
        key: NPC_ANIMATION_KEYS.LADYCAT_IDLE_RIGHT,
        repeat: -1,
        ignoreIfPlaying: true,
      },
      WALK_UP: {
        key: NPC_ANIMATION_KEYS.LADYCAT_IDLE_LEFT,
        repeat: -1,
        ignoreIfPlaying: true,
      },
      WALK_LEFT: {
        key: NPC_ANIMATION_KEYS.LADYCAT_IDLE_LEFT,
        repeat: -1,
        ignoreIfPlaying: true,
      },
      WALK_RIGHT: {
        key: NPC_ANIMATION_KEYS.LADYCAT_IDLE_RIGHT,
        repeat: -1,
        ignoreIfPlaying: true,
      },
    };

    this.#racingCat = new RacingCat({
      scene: this.#scene,
      position: startPos,
      animationConfig,
    });

    // Set initial direction
    this.#racingCat.direction = DIRECTION.RIGHT;
  }

  /**
   * Starts the race timer
   */
  public startRace(): void {
    this.#raceStartTime = this.#scene.time.now;
  }

  /**
   * Updates the racing cat's position along the path
   */
  public update(): void {
    if (!this.#racingCat || this.#racePath.length === 0) {
      return;
    }

    const elapsed = (this.#scene.time.now - this.#raceStartTime) / 1000; // seconds
    const progress = Math.min(elapsed / this.#raceTime, 1); // 0 to 1

    // Calculate target distance along path
    const targetDistance = this.#racePathDistance * progress;

    // Find position along path
    let accumulatedDistance = 0;
    for (let i = 0; i < this.#racePath.length - 1; i++) {
      const dx = this.#racePath[i + 1].x - this.#racePath[i].x;
      const dy = this.#racePath[i + 1].y - this.#racePath[i].y;
      const segmentDistance = Math.hypot(dx, dy);

      if (accumulatedDistance + segmentDistance >= targetDistance) {
        // Position is in this segment
        const segmentProgress =
          (targetDistance - accumulatedDistance) / segmentDistance;
        const x =
          this.#racePath[i].x +
          dx * segmentProgress -
          this.#racingCat.width / 2;
        const y =
          this.#racePath[i].y +
          dy * segmentProgress -
          this.#racingCat.height / 2;
        this.#racingCat.setPosition(x, y);

        // Update direction based on movement
        if (Math.abs(dx) > Math.abs(dy)) {
          this.#racingCat.direction = dx > 0 ? DIRECTION.RIGHT : DIRECTION.LEFT;
        } else {
          this.#racingCat.direction = dy > 0 ? DIRECTION.DOWN : DIRECTION.UP;
        }

        // Play walk animation
        this.#racingCat.setMoveState();
        return;
      }

      accumulatedDistance += segmentDistance;
    }

    // If we've reached the end, stay at final position
    const finalPos = this.#racePath[this.#racePath.length - 1];
    this.#racingCat.setPosition(
      finalPos.x - this.#racingCat.width / 2,
      finalPos.y - this.#racingCat.height / 2,
    );
    this.#racingCat.setIdleState();
  }

  /**
   * Destroys the racing cat
   */
  public destroyRacingCat(): void {
    if (this.#racingCat) {
      this.#racingCat.destroy();
      this.#racingCat = null;
    }
  }
}
