import { type TeamHuntState } from "@hunt/public-client";
import React from "react";
import { hydrateRoot } from "react-dom/client";
import { ErrataDataProvider } from "../../../client/ErrataProvider";
import GameworldZoneClient from "../../../components/overworld/GameworldZoneClient";
import { loadKittyCityScenes } from "../gameworld/scene-loaders/kitty-city";
import KittyCityBody from "./KittyCityBody";
import { type KittyCityState } from "./types";

const KittyCityManager = ({
  initialState,
  initialTeamState,
}: {
  initialState: KittyCityState;
  initialTeamState: TeamHuntState;
}) => {
  return (
    <ErrataDataProvider initialTeamState={initialTeamState}>
      <GameworldZoneClient
        roundSlug="kitty_city"
        initialState={initialState}
        initialTeamState={initialTeamState}
        sceneLoader={loadKittyCityScenes}
        render={({ state, teamState, gameNode }) => {
          return (
            <KittyCityBody
              state={state}
              teamState={teamState}
              gameNode={gameNode}
            />
          );
        }}
      />
    </ErrataDataProvider>
  );
};

const elem = document.getElementById("kitty_city-root");
if (elem) {
  const { initialKittyCityState: state, initialTeamState } =
    window as unknown as {
      initialKittyCityState: KittyCityState;
      initialTeamState: TeamHuntState;
    };
  hydrateRoot(
    elem,
    <KittyCityManager
      initialState={state}
      initialTeamState={initialTeamState}
    />,
  );
} else {
  console.error(
    "Could not mount KittyCityManager because #kitty_city-root was nowhere to be found",
  );
}
