import * as Phaser from "phaser";
import { ASSET_KEYS } from "../common/assets";
import * as CONFIG from "../common/config";
import {
  DEFAULT_UI_TEXT_STYLE,
  DIRECTION,
  STORY_FLAG as STORY_FLAGS,
} from "../common/constants";
import { CUSTOM_EVENTS, EVENT_BUS } from "../common/event-bus";
import {
  TILED_LAYER_NAMES,
  TILED_TILESET_NAMES,
} from "../common/tiled/constants";
import {
  getAllLayerNamesWithPrefix,
  getTiledGateObjectsFromMap,
  getTiledRegiDeskObjectsFromMap,
} from "../common/tiled/utils";
import { type InteractiveGameObject } from "../common/types";
import { isPositionOnIce } from "../common/utils";
import { CHARACTER_STATES } from "../components/state-machine/states/character-states";
import { RacingCatManager } from "../entities/npcs/racing-cat";
import { InteractiveDesk } from "../entities/objects/catsle/interactive_desk";
import { Gate } from "../entities/objects/gate";
import { BaseGameScene } from "./base-game-scene";
import { SCENE_KEYS } from "./scene-keys";

const STORY_FLAG = "kitty_city11";

export class KittyCityGameScene extends BaseGameScene {
  private iceLayer: Phaser.Tilemaps.TilemapLayer | null = null;

  readonly #RACE_TIME = 50; // seconds
  readonly #NUM_LAPS = 2; // Number of laps required to complete the race
  // Gates state
  #gatesByRoomId = new Map<number, Gate[]>();
  #gatesByOrder = new Map<number, Gate>();
  #nextGateOrder = 1; // Track which gate order should be activated next (starts at 1)

  // Racing state
  #isRacing = false;
  #currentLap = 1; // Track current lap (starts at 1, up to #NUM_LAPS)
  #raceTimer: Phaser.Time.TimerEvent | null = null;
  #raceTimeRemaining = this.#RACE_TIME; // seconds
  #countdownText: Phaser.GameObjects.Text | null = null;
  #lapText: Phaser.GameObjects.Text | null = null;
  #countdownTimer: Phaser.Time.TimerEvent | null = null;
  #countdownDelayedCall: Phaser.Time.TimerEvent | null = null;
  #roomToDesks = new Map<number, InteractiveDesk[]>();

  // Racing cat manager
  #racingCatManager: RacingCatManager | null = null;

  // Button sequence tracking
  private readonly correctButtonSequence: number[] = [
    6, 6, 4, 4, 4, 4, 4, 4, 8,
  ];
  private allButtonPresses: number[] = [];
  private isSequenceComplete = false;

  constructor() {
    super(SCENE_KEYS.KITTY_CITY_GAME_SCENE);
  }

  #handleStartRace = (): void => {
    this.startRace();
  };

  #handleEndRace = (data: { success: boolean }): void => {
    this.#endRace(data.success);
  };

  public create(): void {
    super.create();
    this.onEnterRoom(this.currentRoomId);

    // Create UI elements early so they're ready when race starts
    this.#countdownText = this.add
      .text(this.cameras.main.centerX, this.cameras.main.centerY - 20, "", {
        ...DEFAULT_UI_TEXT_STYLE,
        fontSize: "64px",
        fontFamily: "monospace",
        color: "#FFFFFF",
        stroke: "#000000",
        strokeThickness: 8,
      })
      .setOrigin(0.5, 0.5)
      .setDepth(2000)
      .setScrollFactor(0, 0)
      .setVisible(false);

    // Lap display text
    this.#lapText = this.add
      .text(this.cameras.main.centerX, 50, "Lap 1/2", {
        ...DEFAULT_UI_TEXT_STYLE,
        fontSize: "16px",
        fontFamily: "monospace",
        color: "#FFFFFF",
        stroke: "#000000",
        strokeThickness: 4,
      })
      .setOrigin(0.5, 0.5)
      .setDepth(2000)
      .setScrollFactor(0, 0)
      .setVisible(false);

    // Listen for race start event from NPC dialogs
    EVENT_BUS.on(CUSTOM_EVENTS.START_RACE, this.#handleStartRace, this);
    EVENT_BUS.on(CUSTOM_EVENTS.END_RACE, this.#handleEndRace, this);

    // Clean up event listeners on shutdown
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      EVENT_BUS.off(CUSTOM_EVENTS.START_RACE, this.#handleStartRace, this);
      EVENT_BUS.off(CUSTOM_EVENTS.END_RACE, this.#handleEndRace, this);
    });
  }

  protected override createLevel(): Phaser.Tilemaps.Tilemap | undefined {
    const map = super.createLevel();
    if (!map) {
      this.iceLayer = null;
      return undefined;
    }

    const collisionTiles = map.addTilesetImage(
      TILED_TILESET_NAMES.COLLISION,
      ASSET_KEYS.COLLISION,
    );

    if (!collisionTiles) {
      this.iceLayer = null;
      return map;
    }

    const iceLayer = map.createLayer(
      TILED_LAYER_NAMES.ICE,
      collisionTiles,
      0,
      0,
    );

    if (iceLayer) {
      this.iceLayer = iceLayer;
      this.iceLayer.setDepth(5).setAlpha(CONFIG.DEBUG_COLLISION_ALPHA);
      this.iceLayer.setTint(0x0000aa);
    } else {
      this.iceLayer = null;
    }

    // Create gates
    this.#createGates(map);

    const rooms = this.#parseRoomLayers(map);
    const regiLayers = rooms.filter((layer) =>
      layer.name.endsWith(`/${TILED_LAYER_NAMES.REGI}`),
    );
    regiLayers.forEach((layer) => {
      this.#createDesks(map, layer.name, layer.roomId);
    });

    return map;
  }

  /**
   * Helper method to parse room layer names and extract room IDs
   */
  #parseRoomLayers(
    map: Phaser.Tilemaps.Tilemap,
  ): { name: string; roomId: number }[] {
    return getAllLayerNamesWithPrefix(map, TILED_LAYER_NAMES.ROOMS).map(
      (layerName: string) => ({
        name: layerName,
        roomId: parseInt(layerName.split("/")[1], 10),
      }),
    );
  }

  #createGates(map: Phaser.Tilemaps.Tilemap): void {
    const rooms = this.#parseRoomLayers(map);
    const gateLayerNames = rooms.filter((layer) =>
      layer.name.endsWith(`/${TILED_LAYER_NAMES.GATES}`),
    );

    gateLayerNames.forEach((layer) => {
      const objects = getTiledGateObjectsFromMap(map, layer.name);
      const gates: Gate[] = [];
      objects.forEach((object) => {
        const gate = new Gate(this, object);
        gates.push(gate);
        this.#gatesByOrder.set(gate.order, gate);
        this.proximityDiscoverableGroup.add(gate);
      });
      if (gates.length > 0) {
        this.#gatesByRoomId.set(layer.roomId, gates);
      }
    });

    // Gates are hidden by default and will be shown when race starts
  }

  /**
   * Resets all gates to inactive state and optionally shows/hides them
   */
  #resetAllGates(visible: boolean): void {
    this.#gatesByOrder.forEach((gate) => {
      gate.reset();
      if (visible) {
        gate.enableObject();
      } else {
        gate.disableObject();
      }
    });
  }

  /**
   * Checks if all gates have been activated
   */
  #areAllGatesCompleted(): boolean {
    for (const gate of this.#gatesByOrder.values()) {
      if (!gate.isActivated) {
        return false;
      }
    }
    return true;
  }

  protected override registerRoundColliders(): void {
    super.registerRoundColliders();

    // Register overlap for gates
    this.physics.add.overlap(
      this.playerObject,
      this.proximityDiscoverableGroup,
      (body, target) => {
        if (target instanceof Gate) {
          // Only allow gate interactions during a race
          if (!this.#isRacing) {
            return;
          }
          // Only activate if this is the next gate in sequence
          if (!target.isActivated && target.order === this.#nextGateOrder) {
            // Mark as activated immediately (synchronous state change only)
            const wasActivated = target.markActivated();
            if (!wasActivated) {
              return;
            }

            this.#nextGateOrder++;

            // Check if all gates are completed for this lap
            this.time.delayedCall(0, () => {
              if (this.#areAllGatesCompleted()) {
                if (this.#currentLap < this.#NUM_LAPS) {
                  // Start next lap
                  this.#currentLap++;
                  this.#nextGateOrder = 1;
                  // Reset all gates for the next lap
                  this.#resetAllGates(true);
                  // Update lap display
                  this.#updateLapText();
                } else {
                  // All laps completed - end the race
                  EVENT_BUS.emit(CUSTOM_EVENTS.END_RACE, { success: true });
                }
              }
            });
          }
          return;
        }
      },
    );
  }

  protected override enableRoomObjects(roomId: number): void {
    super.enableRoomObjects(roomId);

    const gates = this.#gatesByRoomId.get(roomId);
    if (gates && this.#isRacing) {
      // Only enable gates if we're racing, otherwise keep them hidden
      gates.forEach((gate) => {
        gate.enableObject();
      });
    }

    const buttons = this.#roomToDesks.get(roomId);
    buttons?.forEach((button) => {
      button.enableObject();
    });
  }

  protected override disableRoomObjects(roomId: number): void {
    super.disableRoomObjects(roomId);

    const gates = this.#gatesByRoomId.get(roomId);
    if (gates) {
      gates.forEach((gate) => {
        gate.disableObject();
      });
    }

    this.#roomToDesks.get(roomId)?.forEach((button) => {
      button.disableObject();
    });
  }

  public isPlayerOnIce(): boolean {
    const player = this.playerObject;
    return isPositionOnIce(this.iceLayer, player.x, player.y);
  }

  /**
   * Starts a race - teleports player to gate 1 and begins countdown
   */
  public startRace(): void {
    this.dataManager.setFlagValue(STORY_FLAGS.race_finished, "in_progress");

    const startGate = this.#gatesByOrder.get(1);
    if (!startGate) {
      console.warn("Cannot start race: gate 1 not found");
      return;
    }

    // Reset race state
    this.#isRacing = false;
    this.#currentLap = 1;
    this.#nextGateOrder = 1;
    this.#raceTimeRemaining = this.#RACE_TIME;

    // Reset all gates to inactive state and show them during countdown
    this.#resetAllGates(true);

    // Create racing cat manager
    this.#racingCatManager = new RacingCatManager({
      scene: this,
      gates: this.#gatesByOrder,
      numLaps: this.#NUM_LAPS,
      raceTime: this.#RACE_TIME,
    });
    this.#racingCatManager.buildRacePath();
    this.#racingCatManager.createRacingCat();

    // Teleport player to gate 1 position
    const gateCenterX = startGate.x + startGate.width / 2;
    const gateCenterY = startGate.y + startGate.height / 2;
    this.playerObject.setPosition(gateCenterX, gateCenterY);

    // Set player to face right
    this.playerObject.direction = DIRECTION.RIGHT;

    // Put player in racing idle state
    this.playerObject.stateMachine.setState(CHARACTER_STATES.RACING_IDLE_STATE);
    this.playerObject.controls.isMovementLocked = true;

    // Start countdown
    this.#startCountdown();
  }

  /**
   * Starts the 3, 2, 1 countdown before race begins
   */
  #startCountdown(): void {
    // Clear any existing countdown timers
    if (this.#countdownTimer) {
      this.#countdownTimer.destroy();
      this.#countdownTimer = null;
    }
    if (this.#countdownDelayedCall) {
      this.#countdownDelayedCall.destroy();
      this.#countdownDelayedCall = null;
    }

    let countdown = 3;
    this.#countdownText?.setVisible(true);
    this.#countdownText?.setText(countdown.toString());

    // Timer is hidden (cat is the visual reference), but we keep it running for win/lose logic

    // Fallback: ensure race starts even if timer is interrupted
    // This will fire after 4 seconds (3 countdown + 0.5s delay + 0.5s buffer)
    const fallbackTimer = this.time.delayedCall(4500, () => {
      // Only trigger if race hasn't started yet
      if (!this.#isRacing && this.playerObject.controls.isMovementLocked) {
        console.warn(
          "Wall race countdown fallback triggered - race should have started",
        );
        this.#countdownText?.setVisible(false);
        this.#beginRace();
      }
    });

    this.#countdownTimer = this.time.addEvent({
      delay: 1000,
      callback: () => {
        countdown--;
        if (countdown > 0) {
          this.#countdownText?.setText(countdown.toString());
        } else if (countdown === 0) {
          this.#countdownText?.setText("GO!");
          // Start the race - store reference to ensure it executes
          this.#countdownDelayedCall = this.time.delayedCall(500, () => {
            // Destroy fallback since we're starting normally
            fallbackTimer.destroy();
            this.#countdownText?.setVisible(false);
            this.#beginRace();
            this.#countdownDelayedCall = null;
          });
        }
      },
      repeat: 3,
      callbackScope: this,
    });
  }

  /**
   * Begins the actual race - starts timer and enables racing movement
   */
  #beginRace(): void {
    // Safety check: ensure movement is unlocked even if called multiple times
    if (this.#isRacing) {
      // Race already started, just ensure movement is unlocked
      this.playerObject.controls.isMovementLocked = false;
      this.playerObject.controls.movementControlsLocked = false;
      return;
    }

    this.#isRacing = true;
    this.playerObject.controls.isMovementLocked = false;
    this.playerObject.controls.movementControlsLocked = false;
    this.playerObject.stateMachine.setState(CHARACTER_STATES.RACING_MOVE_STATE);

    // Setup lap text (timer text removed - cat is the visual reference)
    this.#setupTimerText();

    // Start the race timer for the cat
    this.#racingCatManager?.startRace();

    // Start race timer (timer display is hidden, but we keep it running for win/lose logic)
    this.#raceTimer = this.time.addEvent({
      delay: 1000,
      callback: () => {
        this.#raceTimeRemaining--;

        if (this.#raceTimeRemaining <= 0) {
          EVENT_BUS.emit(CUSTOM_EVENTS.END_RACE, { success: false });
        }
      },
      repeat: this.#RACE_TIME - 1, // RACE_TIME seconds total
    });
  }

  /**
   * Updates the lap text position to be centered at the top of the screen
   */
  #updateTimerPosition(): void {
    if (this.#lapText) {
      this.#lapText.setOrigin(0.5, 0.5);
      this.#lapText.setPosition(
        this.cameras.main.centerX,
        this.cameras.main.centerY - 100,
      );
    }
  }

  /**
   * Sets up the timer text to be visible and positioned correctly
   */
  #setupTimerText(): void {
    if (this.#lapText) {
      this.#updateTimerPosition();
      this.#lapText.setVisible(true);
      this.#lapText.setActive(true);
      this.#lapText.setAlpha(1);
      this.#updateLapText();
    }
  }

  /**
   * Updates the lap text to show current lap
   */
  #updateLapText(): void {
    if (this.#lapText) {
      this.#lapText.setText(`Lap ${this.#currentLap}/${this.#NUM_LAPS}`);
    }
  }

  /**
   * Ends the race
   */
  #endRace(success: boolean): void {
    this.#isRacing = false;

    // Stop timer
    if (this.#raceTimer) {
      this.#raceTimer.destroy();
      this.#raceTimer = null;
    }

    // Hide UI
    this.#lapText?.setVisible(false);
    this.#countdownText?.setVisible(false);

    // Show dialog based on race result
    if (success) {
      EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
        messages: ["Congratulations you won the race!"],
      });
    } else {
      EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
        messages: ["You lost the race! Talk to Burnham to try again."],
      });
      // Set race_finished flag to unlocked when race is lost
      this.dataManager.setFlagValue(STORY_FLAGS.race_finished, "unlocked");
      this.refreshLevelObjects();
    }

    // Reset all gates to inactive state and hide them
    this.#resetAllGates(false);

    // Clean up racing cat
    this.#racingCatManager?.destroyRacingCat();
    this.#racingCatManager = null;

    // Handle story flags for activated gates (only at race end to avoid refreshLevelObjects during race)
    if (success) {
      // Defer story flag handling to avoid blocking race end UI
      this.time.delayedCall(0, () => {
        for (const gate of this.#gatesByOrder.values()) {
          if (gate.storyFlag) {
            this.dataManager.setFlagToCompleted(gate.storyFlag);
            this.refreshLevelObjects();
          }
        }
      });
    }

    // Reset player state to normal movement
    this.playerObject.controls.isMovementLocked = false;
    this.playerObject.stateMachine.setState(CHARACTER_STATES.IDLE_STATE);
  }

  protected override registerRoundEvents(): void {
    super.registerRoundEvents();

    EVENT_BUS.on(CUSTOM_EVENTS.ROOM_ENTERED, this.onEnterRoom, this);
    this.onEnterRoom(this.currentRoomId);
  }

  protected override unregisterRoundEvents(): void {
    super.unregisterRoundEvents();
    EVENT_BUS.off(CUSTOM_EVENTS.ROOM_ENTERED, this.onEnterRoom, this);
  }

  protected onEnterRoom = (roomId: number): void => {
    const camera = this.cameras.main;
    camera.postFX.clear();

    if (roomId === 1) {
      const colorMatrix =
        camera.postFX.addColorMatrix() as Phaser.Display.ColorMatrix;
      colorMatrix.saturate(-1); // Fully desaturate
      colorMatrix.saturate(0.5);
      colorMatrix.contrast(0.1);

      const matrix = colorMatrix.getData();
      matrix[12] *= 1.3;
      colorMatrix.set(matrix);

      camera.postFX.addGlow(0xaaccff, 1.5, 0.25, false, 0.05, 8);
    }
  };

  public override update(): void {
    super.update();

    // Update lap text position to follow camera (only if visible)
    if (this.#lapText?.visible) {
      this.#updateTimerPosition();
    }

    // Handle wall collisions during racing by checking if velocity was stopped
    if (this.#isRacing) {
      const playerBody = this.playerObject.physicsBody;
      if (playerBody) {
        // Only zero out tiny velocities when actually blocked on that axis
        if (
          (playerBody.blocked.left || playerBody.blocked.right) &&
          Math.abs(playerBody.velocity.x) < 1
        ) {
          playerBody.velocity.x = 0;
        }
        if (
          (playerBody.blocked.up || playerBody.blocked.down) &&
          Math.abs(playerBody.velocity.y) < 1
        ) {
          playerBody.velocity.y = 0;
        }
      }

      // Update racing cat position
      this.#racingCatManager?.update();
    }
  }

  #createDesks(
    map: Phaser.Tilemaps.Tilemap,
    layerName: string,
    roomId: number,
  ): void {
    if (!this.#roomToDesks.has(roomId)) {
      this.#roomToDesks.set(roomId, []);
    }

    const validTiledObjects = getTiledRegiDeskObjectsFromMap(map, layerName);
    validTiledObjects.forEach((object) => {
      const desk = new InteractiveDesk(
        this,
        object,
        STORY_FLAG,
        this.dataManager,
        (id: number) => {
          return this.#handleDeskPress(id);
        },
      );
      this.#roomToDesks.get(roomId)?.push(desk);
    });
  }

  /**
   * Handles button press and checks sequence
   */
  #handleDeskPress(id: number): boolean {
    if (this.isSequenceComplete) {
      return true;
    }

    // Add button to the sequence of all presses
    this.allButtonPresses.push(id);

    if (this.allButtonPresses.length > this.correctButtonSequence.length) {
      this.allButtonPresses = this.allButtonPresses.slice(
        -this.correctButtonSequence.length,
      );
    }

    // Check if the sequence now ends with the correct answer
    if (
      this.allButtonPresses.join("") === this.correctButtonSequence.join("")
    ) {
      this.#onSequenceComplete();
      return true;
    }

    return true;
  }

  /**
   * Called when the correct button sequence is completed
   */
  #onSequenceComplete(): void {
    this.isSequenceComplete = true;
    this.dataManager.setFlagToCompleted(STORY_FLAG);
    this.dataManager.completeInteraction(STORY_FLAG);
    EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
      messages: ["A secret door appeared!"],
      choices: [],
    });
  }

  protected override appendRoomInteractiveObjects(
    roomId: number,
    objects: InteractiveGameObject[],
  ): void {
    const desks = this.#roomToDesks.get(roomId);
    desks?.forEach((desk) => {
      objects.push(desk);
    });
  }
}
