import * as Phaser from "phaser";
import { ASSET_KEYS } from "../../common/assets";
import type { TiledGateObject } from "../../common/tiled/types";
import type { CustomObject } from "../../common/types";

export class Gate extends Phaser.GameObjects.Zone implements CustomObject {
  #storyFlag?: string;
  #texture: string;
  #order: number;
  #sprite?: Phaser.GameObjects.Sprite;
  #isActivated = false;

  constructor(scene: Phaser.Scene, config: TiledGateObject) {
    // Create zone with size from config, with padding for better collision detection
    super(
      scene,
      config.x - 4,
      config.y - 4,
      config.width + 8,
      config.height + 8,
    );

    this.#storyFlag = config.storyFlag;
    this.#texture = config.texture;
    this.#order = config.order;

    this.setOrigin(0, 0);
    scene.add.existing(this);
    scene.physics.world.enable(this);
    (this.body as Phaser.Physics.Arcade.Body).setImmovable(true);

    // Create the visual sprite
    this.#createSprite();

    // Initially disabled
    this.disableObject();
  }

  get storyFlag(): string | undefined {
    return this.#storyFlag;
  }

  get order(): number {
    return this.#order;
  }

  get isActivated(): boolean {
    return this.#isActivated;
  }

  /**
   * Resets the gate to unactivated state
   */
  public reset(): void {
    this.#isActivated = false;
  }

  /**
   * Creates the visual sprite for the gate
   */
  #createSprite(): void {
    // Account for the -4 offset we added in constructor
    const centerX = this.x + 4 + (this.width - 8) / 2;
    const centerY = this.y + 4 + (this.height - 8) / 2;

    // Always use GATES atlas, with texture as the frame name (defaults to "FLAG_BLUE")
    this.#sprite = this.scene.add.sprite(
      centerX,
      centerY,
      ASSET_KEYS.GATES,
      this.#texture,
    );

    this.#sprite.setOrigin(0.5, 0.5);
    this.#sprite.setDepth(this.depth + 1);
    this.#sprite.setVisible(false);
  }

  /**
   * Marks the gate as activated (synchronous state change only)
   * Returns true if the gate was successfully activated, false if already activated
   */
  public markActivated(): boolean {
    if (this.#isActivated) {
      return false;
    }
    this.#isActivated = true;
    return true;
  }

  /**
   * Applies visual effects for an activated gate - simply hides the sprite
   * Should be called after markActivated() in a deferred callback
   */
  public applyActivationVisuals(): void {
    if (!this.#isActivated || !this.#sprite) {
      return;
    }

    // Hide the sprite to show the player "picked up" the flag
    this.#sprite.setVisible(false);
  }

  public disableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = false;
    this.active = false;
    this.visible = false;
    if (this.#sprite) {
      this.#sprite.setVisible(false);
    }
  }

  public enableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = true;
    this.active = true;
    this.visible = true; // Zones are invisible by default, but need visible=true for collision detection

    // Sprite visibility is disabled - gates are invisible (racing cat serves as visual reference)
    if (this.#sprite) {
      this.#sprite.setVisible(false);
    }
  }
}
